import pandas as pd
def range_problems(row):
    problems=[]
    if pd.notna(row['avg_check']) and not 50<=row['avg_check']<=3000:problems.append('avg_check: вне диапазона')
    if not 0<=row['delivery_share']<=1:problems.append('delivery_share: вне диапазона')
    if row['visits_90d']<0:problems.append('visits_90d: меньше0')
    return problems
bad=P.apply(lambda r:bool(range_problems(r)),axis=1)
would_reject=P.assign(bad=bad).groupby('client').bad.mean().round(3)
rejected_32=int((bad & (P.client=='app 3.2')).sum())
first_bad=pd.to_datetime(P.loc[bad,'ts']).min().strftime('%Y-%m-%d %H:%M')
print(would_reject,rejected_32,first_bad)
